Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<label for="armAngle">Arm position (seek)
  <input type="range" id="armAngle" min="0" max="1" step="0.01" value="0.5">
</label>
<button id="spinPlatter">▶ Spin platter</button>
<div style="margin-top:4px;font-weight:bold;">Demo steps</div>
<button id="step0">1 · Seek to an outer track</button>
<button id="step1">2 · Seek toward the spindle</button>
<button id="step2">3 · Spin to reach a sector</button>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// element spec (world units, see GEOMETRY NOTES):
//   top platter    → CylinderGeometry(r=3, h=0.18) at y=+0.35, face #d9d9d9, edge #808080, dark rim rings
//   bottom platter → same at y=-0.35
//   spindle        → CylinderGeometry(r=0.08, h=3.4) #555555 at y=0.1 (static, in root)
//   track rings    → 6 LineLoop circles radii 1.0..2.7 on top face, gray; selected ring recolored #cc3300
//   rotation arrow → Line arc r=2.2 + ConeGeometry head, black, static in root
//   surface marks  → 10 small dark boxes on top face (spin feedback)
//   pivot post     → CylinderGeometry(r=0.09, h=1.4) at (4.6, 0, 1.2) #777
//   actuator arm   → ExtrudeGeometry tapered flat shape + pad cylinder r=0.45 + black squashed-sphere head, x2
//   seek hint      → small double-headed arrow riding with the upper arm
// Root group is tilted about X so horizontal platters read as ellipses in the front-on oblique view.

const root = new THREE.Group();
root.rotation.x = -0.5;
scene.add(root);

const spinGroup = new THREE.Group();   // platters + tracks + marks (what physically rotates)
root.add(spinGroup);

const R_PLATTER = 3, PLATTER_H = 0.18, Y_TOP = 0.35, Y_BOT = -0.35;
const FACE_TOP = Y_TOP + PLATTER_H / 2;                 // 0.44
const FACE_BOT = Y_BOT - PLATTER_H / 2;                 // -0.44
const matBlack = new THREE.MeshBasicMaterial({ color: 0x000000 });
const matArm = new THREE.MeshBasicMaterial({ color: 0x999999 });
const matLineDark = new THREE.LineBasicMaterial({ color: 0x333333 });

/* ── Platters ─────────────────────────────────────────────────────────── */
function makePlatter(y) {
  const mats = [
    new THREE.MeshBasicMaterial({ color: 0x808080 }),   // side / edge
    new THREE.MeshBasicMaterial({ color: 0xd9d9d9 }),   // top face
    new THREE.MeshBasicMaterial({ color: 0xd9d9d9 }),   // bottom face
  ];
  const m = new THREE.Mesh(new THREE.CylinderGeometry(R_PLATTER, R_PLATTER, PLATTER_H, 72), mats);
  m.position.y = y;
  spinGroup.add(m);
  // rim outlines (thin dark rings at both circular edges)
  for (const dy of [-PLATTER_H / 2, PLATTER_H / 2]) {
    const pts = [];
    for (let i = 0; i <= 72; i++) {
      const a = (i / 72) * Math.PI * 2;
      pts.push(new THREE.Vector3(R_PLATTER * Math.cos(a), y + dy, R_PLATTER * Math.sin(a)));
    }
    spinGroup.add(new THREE.LineLoop(new THREE.BufferGeometry().setFromPoints(pts), matLineDark));
  }
  return m;
}
const platterTopMesh = makePlatter(Y_TOP);
makePlatter(Y_BOT);

/* ── Spindle (static) ─────────────────────────────────────────────────── */
const spindle = new THREE.Mesh(
  new THREE.CylinderGeometry(0.08, 0.08, 3.4, 20),
  new THREE.MeshBasicMaterial({ color: 0x555555 })
);
spindle.position.y = 0.1;
root.add(spindle);

/* ── Track rings on the top face ──────────────────────────────────────── */
const trackRadii = [1.0, 1.34, 1.68, 2.02, 2.36, 2.7];
const trackLines = trackRadii.map((r) => {
  const pts = [];
  for (let i = 0; i <= 96; i++) {
    const a = (i / 96) * Math.PI * 2;
    pts.push(new THREE.Vector3(r * Math.cos(a), FACE_TOP + 0.006, r * Math.sin(a)));
  }
  const ln = new THREE.LineLoop(
    new THREE.BufferGeometry().setFromPoints(pts),
    new THREE.LineBasicMaterial({ color: 0x666666 })
  );
  spinGroup.add(ln);
  return ln;
});

/* ── Surface marks so rotation is visible ─────────────────────────────── */
const matMark = new THREE.MeshBasicMaterial({ color: 0x444444 });
[1.25, 1.85, 2.45].forEach((r, ri) => {
  const n = ri === 1 ? 4 : 3;
  for (let k = 0; k < n; k++) {
    const a = (k / n) * Math.PI * 2 + ri * 0.9;
    const dash = new THREE.Mesh(new THREE.BoxGeometry(0.16, 0.012, 0.05), matMark);
    dash.position.set(r * Math.cos(a), FACE_TOP + 0.008, r * Math.sin(a));
    dash.rotation.y = -a;                    // tangential dashes
    spinGroup.add(dash);
  }
});

/* ── Curved rotation-direction arrow (static annotation) ──────────────── */
{
  const pts = [];
  const a0 = THREE.MathUtils.degToRad(150), a1 = THREE.MathUtils.degToRad(255);
  for (let i = 0; i <= 40; i++) {
    const a = a0 + (a1 - a0) * (i / 40);
    pts.push(new THREE.Vector3(2.2 * Math.cos(a), FACE_TOP + 0.03, 2.2 * Math.sin(a)));
  }
  root.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts),
    new THREE.LineBasicMaterial({ color: 0x000000 })));
  const tip = new THREE.Mesh(new THREE.ConeGeometry(0.07, 0.22, 10), matBlack);
  const ea = a1;
  tip.position.set(2.2 * Math.cos(ea), FACE_TOP + 0.03, 2.2 * Math.sin(ea));
  const tangent = new THREE.Vector3(-Math.sin(ea), 0, Math.cos(ea)).normalize();
  tip.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), tangent);
  root.add(tip);
}

/* ── Pivot post + actuator arms ───────────────────────────────────────── */
const POST = new THREE.Vector3(4.6, 0, 1.2);
const PHI = Math.atan2(POST.z, POST.x);
const L_ARM = 5.09;                       // solved so ± swing spans head radii 2.7..1.0
const A_BASE = THREE.MathUtils.degToRad(81.05);
const SWEEP = THREE.MathUtils.degToRad(22);

const post = new THREE.Mesh(new THREE.CylinderGeometry(0.09, 0.09, 1.45, 16),
  new THREE.MeshBasicMaterial({ color: 0x777777 }));
post.position.copy(POST);
root.add(post);

function makeArm(headOnTop) {
  const g = new THREE.Group();
  const shape = new THREE.Shape();
  shape.moveTo(0.55, 0.15);
  shape.lineTo(L_ARM - 0.28, 0.05);
  shape.quadraticCurveTo(L_ARM - 0.04, 0.02, L_ARM - 0.04, 0);
  shape.quadraticCurveTo(L_ARM - 0.04, -0.02, L_ARM - 0.28, -0.05);
  shape.lineTo(0.55, -0.15);
  shape.quadraticCurveTo(0.40, 0, 0.55, 0.15);
  const geo = new THREE.ExtrudeGeometry(shape, { depth: 0.07, bevelEnabled: false });
  geo.rotateX(Math.PI / 2);
  geo.translate(0, 0.035, 0);
  g.add(new THREE.Mesh(geo, matArm));
  const pad = new THREE.Mesh(new THREE.CylinderGeometry(0.45, 0.45, 0.1, 28), matArm);
  g.add(pad);
  const head = new THREE.Mesh(new THREE.SphereGeometry(0.11, 16, 12), matBlack);
  head.scale.set(1, 0.7, 1);
  head.position.set(L_ARM - 0.18, headOnTop ? 0.09 : -0.09, 0);
  g.add(head);
  return { g, head };
}

const upperArm = makeArm(false);   // head faces down onto top platter
upperArm.g.position.set(POST.x, FACE_TOP + 0.16, POST.z);
root.add(upperArm.g);
const lowerArm = makeArm(true);    // head faces up at underside of lower platter
lowerArm.g.position.set(POST.x, FACE_BOT - 0.16, POST.z);
root.add(lowerArm.g);

/* ── Subtle double-headed seek hint riding with the upper arm ─────────── */
{
  const hint = new THREE.Group();
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.015, 0.015, 0.5, 8),
    new THREE.MeshBasicMaterial({ color: 0x444444 }));
  shaft.rotation.z = Math.PI / 2;
  hint.add(shaft);
  for (const s of [-1, 1]) {
    const c = new THREE.Mesh(new THREE.ConeGeometry(0.05, 0.12, 8),
      new THREE.MeshBasicMaterial({ color: 0x444444 }));
    c.rotation.z = s > 0 ? -Math.PI / 2 : Math.PI / 2;
    c.position.x = s * 0.3;
    hint.add(c);
  }
  hint.position.set(L_ARM - 0.55, 0.2, 0.42);
  upperArm.g.add(hint);
}

/* ── Seek kinematics: slider s in [0,1] -> head radius 2.7 (outer) .. 1.0 (inner) ── */
function headRadius(s) { return 2.7 - 1.7 * s; }
function headPoint(s) {
  const r = headRadius(s);
  const th = PHI - (A_BASE + s * SWEEP);
  return new THREE.Vector3(r * Math.cos(th), 0, r * Math.sin(th));
}
function updateArm(s) {
  const h = headPoint(s);
  const dx = h.x - POST.x, dz = h.z - POST.z;
  const psi = Math.atan2(-dz, dx);
  upperArm.g.rotation.y = psi;
  lowerArm.g.rotation.y = psi;
  // highlight whichever track the head tip is over
  const r = headRadius(s);
  let best = 0, bd = Infinity;
  trackRadii.forEach((tr, i) => { const d0 = Math.abs(tr - r); if (d0 < bd) { bd = d0; best = i; } });
  trackLines.forEach((ln, i) => ln.material.color.set(i === best ? 0xcc3300 : 0x666666));
}

/* ── Camera, leader lines, labels ─────────────────────────────────────── */
root.updateMatrixWorld(true);

function leader(x1, y1, z1, x2, y2, z2) {
  root.add(new THREE.Line(
    new THREE.BufferGeometry().setFromPoints(
      [new THREE.Vector3(x1, y1, z1), new THREE.Vector3(x2, y2, z2)]),
    matLineDark));
}
leader(-2.5, FACE_TOP + 0.01, 1.2, -3.25, 0.85, 1.05);   // platter
leader(0.09, 1.55, 0, 0.05, 1.98, 0);                    // spindle
leader(0.3, FACE_TOP + 0.01, -1.66, 0.65, 0.8, -2.15);   // track
leader(POST.x, -0.75, POST.z, 4.75, -1.15, 1.45);        // arms

const lw = (x, y, z) => root.localToWorld(new THREE.Vector3(x, y, z));

setCameraView({ projection: 'oblique', obliqueAngleDeg: 45, depthScale: 0.5, rollDeg: 0, heightFraction: 0.65 });

addLabel('platter', lw(-3.25, 0.85, 1.05), { offset: [-42, -26], bold: true });
addLabel('spindle', lw(0.05, 1.98, 0), { offset: [14, -22], bold: true });
addLabel('track', lw(0.65, 0.8, -2.15), { offset: [30, -34], bold: true });
const headLabel = addLabel('read/write<br>head', new THREE.Vector3(), { offset: [78, -46], bold: true });
addLabel('arms', lw(4.75, -1.15, 1.45), { offset: [30, 48], bold: true });

/* ── Interaction explanations ─────────────────────────────────────────── */
registerInteractive(platterTopMesh, {
  title: 'Platter',
  body: 'A circular magnetic disk. Both surfaces store data in concentric tracks; the stack spins together around the spindle.',
  tooltip: 'Platter — spinning magnetic disk',
});
registerInteractive(upperArm.head, {
  title: 'Read/write head',
  body: 'The tiny head flies just above the surface. The arm seeks radially to the right track, then the platter rotation brings the desired sector underneath.',
  tooltip: 'Read/write head',
});
registerInteractive(upperArm.g, {
  title: 'Actuator arm',
  body: 'Swings about the pivot post so the head can reach any radius from the inner to the outer track — this radial motion is the seek.',
  tooltip: 'Actuator arm (seek motion)',
});

/* ── Controls: seek slider, spin toggle, demo steps ───────────────────── */
const slider = document.getElementById('armAngle');
const spinBtn = document.getElementById('spinPlatter');
let spinning = false;
slider.addEventListener('input', () => updateArm(parseFloat(slider.value)));

function setSpin(on) {
  spinning = on;
  spinBtn.textContent = on ? '⏸ Stop platter' : '▶ Spin platter';
  spinBtn.classList.toggle('active', on);
}
spinBtn.addEventListener('click', () => setSpin(!spinning));

const STEPS = [
  { armAngle: 0.15, spin: false },
  { armAngle: 0.85, spin: false },
  { armAngle: 0.85, spin: true },
];
let tweenId = null;
function goToStep(i) {
  const st = STEPS[i];
  const from = parseFloat(slider.value);
  const to = st.armAngle;
  const t0 = performance.now();
  if (tweenId) cancelAnimationFrame(tweenId);
  const step = (now) => {
    const k = Math.min(1, (now - t0) / 700);
    const e = k * k * (3 - 2 * k);
    const v = from + (to - from) * e;
    slider.value = v;
    updateArm(v);
    if (k < 1) tweenId = requestAnimationFrame(step);
  };
  tweenId = requestAnimationFrame(step);
  setSpin(st.spin);
  document.querySelectorAll('#ui button[id^="step"]').forEach((b, j) =>
    b.classList.toggle('active', j === i));
}
document.getElementById('step0').addEventListener('click', () => goToStep(0));
document.getElementById('step1').addEventListener('click', () => goToStep(1));
document.getElementById('step2').addEventListener('click', () => goToStep(2));

/* ── Figure loop: spin + head label tracking ──────────────────────────── */
const _hv = new THREE.Vector3();
function figLoop() {
  requestAnimationFrame(figLoop);
  if (spinning) spinGroup.rotation.y += 0.025;
  upperArm.head.getWorldPosition(_hv);
  headLabel.pos.copy(_hv);
}
updateArm(0.5);
figLoop();
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

