Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<label for="armAngle">Arm position (seek)
  <input type="range" id="armAngle" min="0" max="1" step="0.01" value="0.5">
</label>
<button id="spinPlatter">▶ Spin platter</button>
<div style="margin-top:6px;font-weight:bold;">Demo steps</div>
<button id="step0">1 · Seek to an outer track</button>
<button id="step1">2 · Seek toward the spindle</button>
<button id="step2">3 · Spin to reach a sector</button>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// element spec (world units, GEOMETRY NOTES):
//   platters x2    → CylinderGeometry(r=3, h=0.18) at y=±0.35, faces #d9d9d9, edges #808080
//   spindle        → CylinderGeometry(r=0.08, h=3.4) #555555, y centered 0.1 (protrudes above/below)
//   track rings    → 6 LineLoop circles, radii 1.0..2.7 on top face, #666666
//   selected track → thick gray ring (cached torus per radius) #cc3300, repositioned with arm
//   rotation arrow → curved Line arc r=2.2 + cone tip, black, static
//   surface marks  → ~10 dark dashes on a few tracks (spin feedback)
//   pivot post     → CylinderGeometry(r=0.09, h≈1.6) at (4.6, 0, 1.2) #777777
//   actuator arms  → tapered extruded flat shape + rounded pad r=0.45 + black head sphere, x2
//   seek hint      → small double-headed arrow riding with the upper arm
// Root group tilted about X so platter tops read as ellipses under the oblique camera.

const root = new THREE.Group();
root.rotation.x = -0.92;
scene.add(root);

const spinGroup = new THREE.Group();   // platters + tracks + marks (physically rotates)
root.add(spinGroup);

/* ── shared materials (declared ONCE) ─────────────────────────────────── */
const matBlack = new THREE.MeshBasicMaterial({ color: 0x000000 });
const matArm = new THREE.MeshBasicMaterial({ color: 0x999999 });
const matLineDark = new THREE.LineBasicMaterial({ color: 0x333333 });
const matTrack = new THREE.LineBasicMaterial({ color: 0x666666 });

/* ── Platters ─────────────────────────────────────────────────────────── */
const R_PLATTER = 3, PLATTER_H = 0.18;
const Y_PLATTERS = [0.35, -0.35];
const FACE_TOP = Y_PLATTERS[0] + PLATTER_H / 2;          // 0.44
const FACE_BOT = Y_PLATTERS[1] - PLATTER_H / 2;          // -0.44

function circlePoints(r, y, n) {
  const pts = [];
  for (let i = 0; i <= n; i++) {
    const a = (i / n) * Math.PI * 2;
    pts.push(new THREE.Vector3(r * Math.cos(a), y, r * Math.sin(a)));
  }
  return pts;
}

Y_PLATTERS.forEach((y) => {
  const mats = [
    new THREE.MeshBasicMaterial({ color: 0x808080 }),   // edge
    new THREE.MeshBasicMaterial({ color: 0xd9d9d9 }),   // top face
    new THREE.MeshBasicMaterial({ color: 0xd9d9d9 }),   // bottom face
  ];
  const m = new THREE.Mesh(new THREE.CylinderGeometry(R_PLATTER, R_PLATTER, PLATTER_H, 72), mats);
  m.position.y = y;
  spinGroup.add(m);
  // rim outlines
  for (const dy of [-PLATTER_H / 2, PLATTER_H / 2]) {
    spinGroup.add(new THREE.LineLoop(
      new THREE.BufferGeometry().setFromPoints(circlePoints(R_PLATTER, y + dy, 72)),
      matLineDark));
  }
});

/* ── Spindle (static, does NOT rotate) ────────────────────────────────── */
const spindle = new THREE.Mesh(
  new THREE.CylinderGeometry(0.08, 0.08, 3.4, 20),
  new THREE.MeshBasicMaterial({ color: 0x555555 })
);
spindle.position.y = 0.1;
root.add(spindle);

/* ── Track rings on the top face ──────────────────────────────────────── */
const trackRadii = [1.0, 1.34, 1.68, 2.02, 2.36, 2.7];
trackRadii.forEach((r) => {
  spinGroup.add(new THREE.LineLoop(
    new THREE.BufferGeometry().setFromPoints(circlePoints(r, FACE_TOP + 0.006, 96)),
    matTrack));
});

// emphasized selected track: thick band; geometries cached per radius so the
// seek tween never allocates/disposes every frame
const selTrackGeoms = new Map();
function selTrackGeom(r) {
  if (!selTrackGeoms.has(r)) selTrackGeoms.set(r, new THREE.TorusGeometry(r, 0.05, 10, 96));
  return selTrackGeoms.get(r);
}
const selTrack = new THREE.Mesh(
  selTrackGeom(2.02),
  new THREE.MeshBasicMaterial({ color: 0xcc3300 })
);
selTrack.rotation.x = Math.PI / 2;
selTrack.position.y = FACE_TOP + 0.02;
spinGroup.add(selTrack);

/* ── Surface marks so rotation is visible ─────────────────────────────── */
{
  const matMark = new THREE.MeshBasicMaterial({ color: 0x444444 });
  [1.25, 1.85, 2.45].forEach((r, ri) => {
    const n = ri === 1 ? 4 : 3;
    for (let k = 0; k < n; k++) {
      const a = (k / n) * Math.PI * 2 + ri * 0.9;
      const dash = new THREE.Mesh(new THREE.BoxGeometry(0.16, 0.012, 0.05), matMark);
      dash.position.set(r * Math.cos(a), FACE_TOP + 0.008, r * Math.sin(a));
      dash.rotation.y = -a;
      spinGroup.add(dash);
    }
  });
}

/* ── Curved rotation-direction arrow (static annotation, in root) ─────── */
{
  const pts = [];
  const a0 = THREE.MathUtils.degToRad(150), a1 = THREE.MathUtils.degToRad(255);
  for (let i = 0; i <= 40; i++) {
    const a = a0 + (a1 - a0) * (i / 40);
    pts.push(new THREE.Vector3(2.2 * Math.cos(a), FACE_TOP + 0.03, 2.2 * Math.sin(a)));
  }
  root.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts),
    new THREE.LineBasicMaterial({ color: 0x000000 })));
  const tip = new THREE.Mesh(new THREE.ConeGeometry(0.07, 0.22, 10), matBlack);
  tip.position.set(2.2 * Math.cos(a1), FACE_TOP + 0.03, 2.2 * Math.sin(a1));
  tip.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0),
    new THREE.Vector3(-Math.sin(a1), 0, Math.cos(a1)).normalize());
  root.add(tip);
}

/* ── Pivot post + actuator arms ───────────────────────────────────────── */
const POST = new THREE.Vector3(4.6, 0, 1.2);
const PHI = Math.atan2(POST.z, POST.x);
const L_ARM = 5.09;                       // ± swing spans head radii 2.7 .. 1.0
const A_BASE = THREE.MathUtils.degToRad(81.05);
const SWEEP = THREE.MathUtils.degToRad(22);

const post = new THREE.Mesh(
  new THREE.CylinderGeometry(0.09, 0.09, (FACE_TOP + 0.16) - (FACE_BOT - 0.16), 16),
  new THREE.MeshBasicMaterial({ color: 0x777777 })
);
post.position.copy(POST);
root.add(post);

function makeArm(headOnTop) {
  const g = new THREE.Group();
  const shape = new THREE.Shape();
  shape.moveTo(0.55, 0.15);
  shape.lineTo(L_ARM - 0.28, 0.05);
  shape.quadraticCurveTo(L_ARM - 0.04, 0.02, L_ARM - 0.04, 0);
  shape.quadraticCurveTo(L_ARM - 0.04, -0.02, L_ARM - 0.28, -0.05);
  shape.lineTo(0.55, -0.15);
  shape.quadraticCurveTo(0.40, 0, 0.55, 0.15);
  const geo = new THREE.ExtrudeGeometry(shape, { depth: 0.07, bevelEnabled: false });
  geo.rotateX(Math.PI / 2);
  geo.translate(0, 0.035, 0);
  g.add(new THREE.Mesh(geo, matArm));
  const pad = new THREE.Mesh(new THREE.CylinderGeometry(0.45, 0.45, 0.1, 28), matArm);
  g.add(pad);
  const head = new THREE.Mesh(new THREE.SphereGeometry(0.11, 16, 12), matBlack);
  head.scale.set(1, 0.7, 1);
  head.position.set(L_ARM - 0.18, headOnTop ? 0.09 : -0.09, 0);
  g.add(head);
  return { g, head };
}

const upperArm = makeArm(false);
upperArm.g.position.set(POST.x, FACE_TOP + 0.16, POST.z);
root.add(upperArm.g);
const lowerArm = makeArm(true);
lowerArm.g.position.set(POST.x, FACE_BOT - 0.16, POST.z);
root.add(lowerArm.g);

/* ── Subtle double-headed seek hint riding with the upper arm ─────────── */
{
  const hint = new THREE.Group();
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.015, 0.015, 0.5, 8),
    new THREE.MeshBasicMaterial({ color: 0x444444 }));
  shaft.rotation.z = Math.PI / 2;
  hint.add(shaft);
  for (const s of [-1, 1]) {
    const c = new THREE.Mesh(new THREE.ConeGeometry(0.05, 0.12, 8),
      new THREE.MeshBasicMaterial({ color: 0x444444 }));
    c.rotation.z = s > 0 ? -Math.PI / 2 : Math.PI / 2;
    c.position.x = s * 0.3;
    hint.add(c);
  }
  hint.position.set(L_ARM - 0.55, 0.2, 0.42);
  upperArm.g.add(hint);
}

/* ── Seek kinematics: slider s in [0,1] -> head radius 2.7 (outer) .. 1.0 (inner) ── */
function headRadius(s) { return 2.7 - 1.7 * s; }
function headPoint(s) {
  const r = headRadius(s);
  const th = PHI - (A_BASE + s * SWEEP);
  return new THREE.Vector3(r * Math.cos(th), 0, r * Math.sin(th));
}
function updateArm(s) {
  const h = headPoint(s);
  const psi = Math.atan2(-(h.z - POST.z), h.x - POST.x);
  upperArm.g.rotation.y = psi;
  lowerArm.g.rotation.y = psi;
  const r = headRadius(s);
  let best = trackRadii[0], bd = Infinity;
  for (const tr of trackRadii) {
    const dd = Math.abs(tr - r);
    if (dd < bd) { bd = dd; best = tr; }
  }
  selTrack.geometry = selTrackGeom(best);   // cached — no per-frame churn
}

/* ── Camera, leader lines, labels ─────────────────────────────────────── */
function leader(x1, y1, z1, x2, y2, z2) {
  root.add(new THREE.Line(
    new THREE.BufferGeometry().setFromPoints(
      [new THREE.Vector3(x1, y1, z1), new THREE.Vector3(x2, y2, z2)]),
    matLineDark));
}
leader(-2.5, FACE_TOP + 0.01, 1.2, -3.4, 1.3, 1.3);      // platter
leader(0.09, 1.5, 0, 0.05, 1.95, 0);                     // spindle
leader(0.3, FACE_TOP + 0.01, -1.68, 0.75, 1.3, -2.4);    // track
leader(POST.x, -0.5, POST.z, 4.9, -1.15, 1.6);           // arms

root.updateMatrixWorld(true);
const lw = (x, y, z) => root.localToWorld(new THREE.Vector3(x, y, z));

setCameraView({ projection: 'oblique', obliqueAngleDeg: 45, depthScale: 0.5, rollDeg: 0, heightFraction: 0.65 });

addLabel('platter', lw(-3.4, 1.3, 1.3), { offset: [-46, -30], bold: true });
addLabel('spindle', lw(0.05, 1.95, 0), { offset: [16, -24], bold: true });
addLabel('track', lw(0.75, 1.3, -2.4), { offset: [-10, -48], bold: true });
const headLabel = addLabel('read/write<br>head', new THREE.Vector3(), { offset: [104, -64], bold: true });
addLabel('arms', lw(4.9, -1.15, 1.6), { offset: [34, 52], bold: true });

/* ── Interaction explanations ─────────────────────────────────────────── */
registerInteractive(spinGroup.children[0], {
  title: 'Platter',
