const slider = document.getElementById('armAngle');
const spinBtn = document.getElementById('spinPlatter');
let spinning = false;
slider.addEventListener('input', () => updateArm(parseFloat(slider.value)));

function setSpin(on) {
  spinning = on;
  spinBtn.textContent = on ? '⏸ Stop platter' : '▶ Spin platter';
  spinBtn.classList.toggle('active', on);
}
spinBtn.addEventListener('click', () => setSpin(!spinning));

const STEPS = [
  { armAngle: 0.15, spin: false },
  { armAngle: 0.85, spin: false },
  { armAngle: 0.85, spin: true },
];
let tweenId = null;
function goToStep(i) {
  const st = STEPS[i];
  const from = parseFloat(slider.value);
  const to = st.armAngle;
  const t0 = performance.now();
  if (tweenId) cancelAnimationFrame(tweenId);
  const step = (now) => {
    const k = Math.min(1, (now - t0) / 700);
    const e = k * k * (3 - 2 * k);
    const v = from + (to - from) * e;
    slider.value = v;
    updateArm(v);
    if (k < 1) tweenId = requestAnimationFrame(step);
  };
  tweenId = requestAnimationFrame(step);
  setSpin(st.spin);
  document.querySelectorAll('#ui button[id^="step"]').forEach((b, j) =>
    b.classList.toggle('active', j === i));
}
document.getElementById('step0').addEventListener('click', () => goToStep(0));
document.getElementById('step1').addEventListener('click', () => goToStep(1));
document.getElementById('step2').addEventListener('click', () => goToStep(2));

