const _hv = new THREE.Vector3();
function figLoop() {
  requestAnimationFrame(figLoop);
  if (spinning) spinGroup.rotation.y += 0.025;
  upperArm.head.getWorldPosition(_hv);
  headLabel.pos.copy(_hv);
}
updateArm(0.5);
figLoop();
